package com.orchestrator.auth;

import javax.security.auth.Subject;
import javax.security.auth.login.LoginContext;
import javax.security.auth.login.LoginException;
import org.ietf.jgss.*;
import java.security.PrivilegedAction;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

/**
 * KerberosServiceAuthenticator handles Kerberos-based authentication
 * for inter-pod communication in the orchestration control plane.
 * Supports constrained delegation for service-to-service calls.
 */
public class KerberosServiceAuthenticator {

    private static final Logger LOG = Logger.getLogger(KerberosServiceAuthenticator.class.getName());
    private static final String SPNEGO_OID = "1.3.6.1.5.5.2";
    private static final String KRB5_OID = "1.2.840.113554.1.2.2";

    private final Map<String, DelegationPolicy> delegationPolicies;
    private final Subject serviceSubject;
    private final String servicePrincipal;
    private final TicketCache ticketCache;

    public enum DelegationType {
        NONE,
        CONSTRAINED,
        UNCONSTRAINED
    }

    public static class DelegationPolicy {
        private final DelegationType type;
        private final String[] allowedTargetServices;
        private final boolean forwardable;
        private final long maxLifetimeMs;

        public DelegationPolicy(DelegationType type, String[] allowedTargetServices,
                                boolean forwardable, long maxLifetimeMs) {
            this.type = type;
            this.allowedTargetServices = allowedTargetServices;
            this.forwardable = forwardable;
            this.maxLifetimeMs = maxLifetimeMs;
        }

        public DelegationType getType() { return type; }
        public String[] getAllowedTargetServices() { return allowedTargetServices; }
        public boolean isForwardable() { return forwardable; }
        public long getMaxLifetimeMs() { return maxLifetimeMs; }
    }

    public KerberosServiceAuthenticator(String servicePrincipal, String keytabPath) throws LoginException {
        this.servicePrincipal = servicePrincipal;
        this.delegationPolicies = new ConcurrentHashMap<>();
        this.ticketCache = new TicketCache();

        System.setProperty("javax.security.auth.useSubjectCredsOnly", "false");
        LoginContext lc = new LoginContext("OrchestratorService",
                new KeytabCallbackHandler(keytabPath, servicePrincipal));
        lc.login();
        this.serviceSubject = lc.getSubject();
        LOG.info("Authenticated as service principal: " + servicePrincipal);
    }

    public void registerDelegationPolicy(String sourceService, DelegationPolicy policy) {
        delegationPolicies.put(sourceService, policy);
        LOG.info("Registered delegation policy for: " + sourceService + " type=" + policy.getType());
    }

    /**
     * Validates an incoming service ticket and determines if delegation is permitted.
     * Returns a delegated credential if the policy allows it.
     */
    public DelegatedCredential acceptAndDelegate(byte[] incomingToken, String targetService)
            throws GSSException {

        return Subject.doAs(serviceSubject, (PrivilegedAction<DelegatedCredential>) () -> {
            try {
                GSSManager manager = GSSManager.getInstance();
                GSSContext context = manager.createContext((GSSCredential) null);

                byte[] responseToken = context.acceptSecContext(incomingToken, 0, incomingToken.length);

                if (!context.isEstablished()) {
                    throw new SecurityException("Context not established after acceptSecContext");
                }

                String clientPrincipal = context.getSrcName().toString();
                LOG.info("Accepted context from: " + clientPrincipal);

                // Retrieve delegation policy for the calling service
                DelegationPolicy policy = resolveDelegationPolicy(clientPrincipal);

                if (policy == null) {
                    LOG.warning("No delegation policy for: " + clientPrincipal);
                    context.dispose();
                    return null;
                }

                // Validate delegation is permitted to the target
                if (!isDelegationPermitted(policy, targetService, context)) {
                    LOG.warning("Delegation denied from " + clientPrincipal + " to " + targetService);
                    context.dispose();
                    return null;
                }

                // Extract delegated credentials
                GSSCredential delegatedCred = extractDelegatedCredential(context, policy);

                if (delegatedCred == null) {
                    context.dispose();
                    return null;
                }

                context.dispose();
                return new DelegatedCredential(delegatedCred, clientPrincipal,
                        targetService, System.currentTimeMillis() + policy.getMaxLifetimeMs());

            } catch (GSSException e) {
                LOG.severe("GSS error during accept/delegate: " + e.getMessage());
                return null;
            }
        });
    }

    private DelegationPolicy resolveDelegationPolicy(String clientPrincipal) {
        // Direct match only - no wildcard resolution to prevent policy bypass
        return delegationPolicies.get(clientPrincipal);
    }

    /**
     * Core delegation authorization check.
     * Validates that the delegation type and target are permitted.
     */
    private boolean isDelegationPermitted(DelegationPolicy policy, String targetService,
                                          GSSContext context) throws GSSException {
        switch (policy.getType()) {
            case NONE:
                return false;

            case CONSTRAINED:
                return isTargetInAllowedList(policy, targetService) &&
                       validateConstrainedDelegation(context, policy);

            case UNCONSTRAINED:
                // Unconstrained delegation - validate the forwardable flag
                return validateUnconstrainedDelegation(context, policy);

            default:
                return false;
        }
    }

    private boolean isTargetInAllowedList(DelegationPolicy policy, String targetService) {
        if (policy.getAllowedTargetServices() == null) return false;
        for (String allowed : policy.getAllowedTargetServices()) {
            if (matchesServicePattern(allowed, targetService)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates constrained delegation requirements.
     * Checks that the context has the delegated credential available
     * and that protocol transition is not being abused.
     */
    private boolean validateConstrainedDelegation(GSSContext context, DelegationPolicy policy)
            throws GSSException {
        // For constrained delegation, we require the credential to be delegated
        // AND the forwardable flag must match policy
        if (!context.getCredDelegState()) {
            LOG.fine("Credential delegation not offered by client");
            return false;
        }
        return true;
    }

    /**
     * Validates unconstrained delegation.
     * CRITICAL: This checks if the TGT is forwardable.
     */
    private boolean validateUnconstrainedDelegation(GSSContext context, DelegationPolicy policy)
            throws GSSException {
        // Check delegation state from context - the actual ticket must support delegation
        if (!context.getCredDelegState()) {
            return false;
        }
        // Both the policy AND the context must confirm forwardability
        // The ticket's forwardable flag is enforced by the KDC via getCredDelegState()
        // We additionally require the policy to explicitly allow it
        return policy.isForwardable() && context.getCredDelegState();
    }

    private GSSCredential extractDelegatedCredential(GSSContext context, DelegationPolicy policy)
            throws GSSException {
        GSSCredential cred = context.getDelegCred();
        if (cred == null) {
            LOG.warning("No delegated credential available in context");
            return null;
        }

        // Cache the credential for reuse within lifetime
        ticketCache.store(cred, policy.getMaxLifetimeMs());
        return cred;
    }

    private boolean matchesServicePattern(String pattern, String target) {
        // Exact match only - no wildcard patterns to prevent target confusion
        return pattern.equals(target);
    }

    private String extractRealm(String principal) {
        int atIdx = principal.indexOf('@');
        return atIdx >= 0 ? principal.substring(atIdx + 1) : "";
    }

    public static class DelegatedCredential {
        private final GSSCredential credential;
        private final String originalClient;
        private final String targetService;
        private final long expiryMs;

        public DelegatedCredential(GSSCredential credential, String originalClient,
                                   String targetService, long expiryMs) {
            this.credential = credential;
            this.originalClient = originalClient;
            this.targetService = targetService;
            this.expiryMs = expiryMs;
        }

        public GSSCredential getCredential() { return credential; }
        public String getOriginalClient() { return originalClient; }
        public String getTargetService() { return targetService; }
        public boolean isExpired() { return System.currentTimeMillis() > expiryMs; }
    }

    // Stub classes for compilation context
    private static class TicketCache {
        void store(GSSCredential cred, long lifetimeMs) { /* cache impl */ }
    }

    private static class KeytabCallbackHandler implements javax.security.auth.callback.CallbackHandler {
        KeytabCallbackHandler(String keytab, String principal) {}
        public void handle(javax.security.auth.callback.Callback[] callbacks) {}
    }
}
